            status: number;
            duration_ms: number;
            /**
             * @description The error's code from GET /v1/error-codes, for a refused or failed call.
             * @example null
             */
            error_code: string | null;
            /**
             * @description The field an invalid request named, such as email (never its value), or the scope a forbidden call was missing, such as leads.manage.
             * @example null
             */
            error_param: string | null;
            /** @enum {string} */
            surface: "web" | "api" | "mcp" | "cli" | "sdk" | "mission";
            /** @description The Outflare-Client header, such as mcp/0.1.0. */
